import{_ as a,a as t}from"./chunks/02c-search-content.8lrBO6Dd.js";import{_ as o,o as r,c as i,a2 as n}from"./chunks/framework.DUZafPzB.js";const m=JSON.parse('{"title":"工作区搜索","description":"","frontmatter":{},"headers":[],"relativePath":"zh/features/search.md","filePath":"zh/features/search.md","lastUpdated":1791422495000}'),l={name:"zh/features/search.md"};function s(c,e,d,h,p,_){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="工作区搜索" tabindex="-1">工作区搜索 <a class="header-anchor" href="#工作区搜索" aria-label="Permalink to &quot;工作区搜索&quot;">​</a></h1><p>侧栏 <strong>Search</strong> 打开浮窗（桌面）或底部 sheet（手机），<strong>不替换</strong>主视图。可按文件名查找，或用正则搜文件内容。</p><p><img src="'+a+'" alt="文件名搜索：REWIND → 5 hits"></p><h2 id="文件名搜索-find" tabindex="-1">文件名搜索（Find） <a class="header-anchor" href="#文件名搜索-find" aria-label="Permalink to &quot;文件名搜索（Find）&quot;">​</a></h2><ol><li>打开 Search，模式选 <strong>Files</strong>。</li><li>选择 root 与子路径（<code>/</code> 表示整个 root）。</li><li>输入名称片段（如 <code>REWIND</code>），点 <strong>Search</strong>。</li><li>结果区显示 hits / scanned；可再 Filter results。</li><li>用眼睛图标预览，或打开文件所在位置。</li></ol><h2 id="内容搜索-content" tabindex="-1">内容搜索（Content） <a class="header-anchor" href="#内容搜索-content" aria-label="Permalink to &quot;内容搜索（Content）&quot;">​</a></h2><p>模式切到 <strong>Content</strong>，输入正则（如 <code>TODO|FIXME</code>）。命中会显示路径、行号与上下文，匹配词高亮。</p><p><img src="'+t+'" alt="内容搜索 TODOFIXME"></p><h2 id="options-可选" tabindex="-1">Options（可选） <a class="header-anchor" href="#options-可选" aria-label="Permalink to &quot;Options（可选）&quot;">​</a></h2><p>展开 Options 可设置：</p><ul><li>扩展名过滤（逗号 / 空格分隔，不是 glob）</li><li>上下文行数（Content 模式）</li><li>最大深度</li><li>忽略的目录名（如 <code>node_modules</code>、<code>venv</code>、<code>renv</code>）</li></ul><h2 id="行为说明" tabindex="-1">行为说明 <a class="header-anchor" href="#行为说明" aria-label="Permalink to &quot;行为说明&quot;">​</a></h2><ul><li>单 Agent 同时只跑一个搜索；可随时 <strong>Cancel</strong>。</li><li>大树请收窄路径、加忽略、限深度。</li><li>进度经 SSE 推送；关闭浮窗不会强制杀掉已在跑的请求（可用 Cancel）。</li><li>搜索使用 Agent 的 <code>workspace_search</code> 能力（当前发布版默认具备）。</li></ul><p>相关：<a href="./browse">浏览文件</a> · <a href="./collections">合集</a></p>',14)])])}const g=o(l,[["render",s]]);export{m as __pageData,g as default};
